import {workApi as api,workMediaApi as mediaApi,setWorkCsrf,workPage} from './work-api.js';
import {mountWorkCapture} from './work-capture.js';
import {mountWorkPlanner} from './work-planner.js';
import {mountProductionPlan,planSceneMarkup} from './production-plan.js';
import {mountWorkThread} from './work-thread.js';

const $=id=>document.getElementById(id);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const page=document.body.dataset.workPage,adminPage=page==='productions';
const zone='America/Phoenix';
const statusNames={draft:'Draft',active:'In progress',completed:'Completed',archived:'Archived',assigned:'Awaiting response',accepted:'Accepted',declined:'Declined',cancelled:'Cancelled',submitted:'In review',changes_requested:'Retake requested',approved:'Approved',retake:'Retake requested',closed:'Closed'};
const state={boot:null,projects:[],mine:{projects:[],assigned:[],open:[],submitted:[],completed:[]},tab:'assigned',limit:18,rosterLimit:12,rosterStale:false,detail:null,detailRequest:0,listRequest:0,notificationRequest:0,mutationBusy:false,formDirty:false,capture:null,planner:null,productionPlan:null,thread:null,notifications:[],route:'',initializing:true};
function safeUrl(value){try{const url=new URL(value,location.href);return ['http:','https:'].includes(url.protocol)&&url.origin===location.origin?url.pathname+url.search+url.hash:'';}catch{return '';}}
function date(value,withTime=false){if(!value)return 'No deadline';const parsed=new Date(value);if(!Number.isFinite(parsed.getTime()))return 'Date unavailable';return new Intl.DateTimeFormat('en-US',{timeZone:zone,month:'short',day:'numeric',year:'numeric',...(withTime?{hour:'numeric',minute:'2-digit'}:{})}).format(parsed);}
function localDate(value){return value?date(value+'-07:00',true):'No deadline';}
function duration(seconds){const total=Math.max(0,Number(seconds)||0);return total>=60?Math.floor(total/60)+'m'+(total%60?' '+Math.round(total%60)+'s':''):Math.round(total)+'s';}
function timecode(ms){const seconds=Math.max(0,Math.floor(Number(ms)/1000)||0);return Math.floor(seconds/60)+':'+String(seconds%60).padStart(2,'0');}
function size(bytes){return Number(bytes)>=1048576?(Number(bytes)/1048576).toFixed(1)+' MB':Math.max(1,Math.round(Number(bytes)/1024))+' KB';}
function toast(message,error=false){const node=$('work-toast');node.textContent=message;node.className='toast visible'+(error?' is-error':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>node.classList.remove('visible'),error?9000:5000);}
function clearError(){$('work-error').hidden=true;$('work-error').textContent='';}
function fail(error){console.error(error);$('work-error').hidden=false;$('work-error').textContent=error.message||String(error);toast(error.message||'Please try again.',true);}
function on(id,event,handler){$(id)?.addEventListener(event,e=>Promise.resolve().then(()=>handler(e)).catch(fail));}
function button(label,action,id='',kind='',extra=''){return '<button type="button" class="button '+kind+'" data-action="'+esc(action)+'" data-id="'+esc(id)+'" '+extra+'>'+esc(label)+'</button>';}
function link(label,url,kind=''){const href=safeUrl(url);return href?'<a class="button '+kind+'" href="'+esc(href)+'">'+esc(label)+'</a>':'';}
function badge(label,kind=''){return '<span class="badge '+kind+'">'+esc(label)+'</span>';}
function statusBadge(status){return badge(statusNames[status]||status,['accepted','approved','completed'].includes(status)?'badge--success':['changes_requested','retake'].includes(status)?'badge--private':['active','submitted'].includes(status)?'badge--accent':'');}
function empty(title,description,actions=''){return '<div class="work-empty"><h3>'+esc(title)+'</h3><p>'+esc(description)+'</p>'+actions+'</div>';}
function field(name,label,value='',type='text',attributes=''){return '<label class="field">'+esc(label)+'<input name="'+name+'" type="'+type+'" value="'+esc(value)+'" '+attributes+'></label>';}
function area(name,label,value='',max=12000,extra=''){return '<label class="field '+extra+'">'+esc(label)+'<textarea name="'+name+'" rows="4" maxlength="'+max+'">'+esc(value)+'</textarea></label>';}
function select(name,label,options,value,extra=''){return '<label class="field '+extra+'">'+esc(label)+'<select name="'+name+'">'+options.map(o=>'<option value="'+esc(o[0])+'"'+(String(o[0])===String(value)?' selected':'')+'>'+esc(o[1])+'</option>').join('')+'</select></label>';}
function formActions(label,cancelAction='back'){return '<div class="work-actions"><button type="submit" class="button button--primary">'+esc(label)+'</button>'+button('Cancel',cancelAction)+'</div><p class="work-form-status" data-form-status role="status"></p>';}
function metrics(values){return values.map(([label,value])=>'<div class="work-metric"><strong>'+esc(value)+'</strong><span>'+esc(label)+'</span></div>').join('');}
function metadata(item){return '<div class="work-meta"><span>'+esc(item.orientation==='any'?'Any orientation':item.orientation||'Any orientation')+'</span>'+(Number(item.targetDurationSeconds)?'<span>About '+esc(duration(item.targetDurationSeconds))+'</span>':'')+'<span>'+esc(item.takesRequested||1)+' take'+(Number(item.takesRequested)===1?'':'s')+' requested</span><span>'+esc(item.dueLocal?'Due '+localDate(item.dueLocal)+' · Arizona':item.dueAt?'Due '+date(item.dueAt,true)+' · Arizona':'No deadline')+'</span></div>';}
function canLeave(){if(state.mutationBusy){toast('Let this save finish before changing views.');return false;}if(state.capture?.isBusy?.()||state.planner?.isBusy?.()||state.productionPlan?.isBusy?.()||state.thread?.isBusy?.()){toast('Let the current recording, upload, plan, or reply finish before changing views.');return false;}if((state.formDirty||state.capture?.isDirty?.()||state.planner?.isDirty?.()||state.productionPlan?.isDirty?.()||state.thread?.isDirty?.())&&!confirm('Leave this view? Unsaved form changes will be lost. Saved recording, plan and reply drafts can be resumed in this browser.'))return false;return true;}
function cleanup(){state.capture?.destroy?.();state.planner?.destroy?.();state.productionPlan?.destroy?.();state.thread?.destroy?.();state.capture=null;state.planner=null;state.productionPlan=null;state.thread=null;state.formDirty=false;}
function canModuleMutate(source){if(state.mutationBusy||state.capture?.isBusy?.()||state.capture?.isDirty?.()||(source!=='planner'&&state.planner?.isBusy?.())||(source!=='plan'&&state.productionPlan?.isBusy?.())||(source!=='thread'&&state.thread?.isBusy?.())){toast('Finish the current save, recording or upload before starting another change.');return false;}return true;}
function updateRoute(kind,id='',replace=false){const url=new URL(location.href);['projectId','shotId','assignmentId','id','project','shot','assignment'].forEach(k=>url.searchParams.delete(k));if(['project','shot','assignment'].includes(kind))url.searchParams.set(kind+'Id',id);if(!adminPage)url.searchParams.set('tab',state.tab);const next=url.pathname+url.search;state.route=next;if(replace)history.replaceState(null,'',next);else if(location.pathname+location.search!==next)history.pushState(null,'',next);}
function setDetail(html,kind,data,options={}){state.detailRequest++;cleanup();state.detail={kind,data};$('work-detail').innerHTML='<div class="work-detail-top">'+button(adminPage?'Back to productions':'Back to my work','list','','button--quiet')+(kind==='shot'||kind==='assignment'?button('View production','project',data.projectId||data.project?.id,'button--quiet'):'')+'</div>'+html;$('work-list-view').hidden=true;$('work-detail').hidden=false;clearError();if(options.route!==false)updateRoute(kind,data?.id||'',!!options.replace);if(options.scroll!==false)$('work-detail').scrollIntoView({behavior:'smooth',block:'start'});}
function showList({force=false,replace=false}={}){if(!force&&!canLeave())return false;state.detailRequest++;cleanup();state.detail=null;$('work-detail').hidden=true;$('work-detail').innerHTML='';$('work-list-view').hidden=false;clearError();updateRoute('list','',replace);renderList();return true;}
function findAssignment(id){if(state.detail?.kind==='assignment'&&state.detail.data.id===id)return state.detail.data;if(state.detail?.kind==='shot')return state.detail.data.assignments?.find(a=>a.id===id);return Object.values(state.mine).flat().find(a=>a.id===id);}
function formKey(form){return [form.dataset.workForm,form.dataset.submissionId||'',form.dataset.projectId||'',form.dataset.shotId||''].join(':');}
function collectFormDrafts(excluded=null){const records=[];for(const form of $('work-detail').querySelectorAll('[data-work-form]')){if(form===excluded)continue;const fields=[...form.querySelectorAll('input[name],textarea[name],select[name]')].filter(control=>!['file','submit','button','hidden'].includes(control.type));const changed=fields.some(control=>['checkbox','radio'].includes(control.type)?control.checked!==control.defaultChecked:control.tagName==='SELECT'?control.value!==([...control.options].find(option=>option.defaultSelected)||control.options[0])?.value:control.value!==control.defaultValue);if(changed)records.push({key:formKey(form),originForm:form,fields:fields.map(control=>({name:control.name,type:control.type,value:control.value,checked:control.checked}))});}return records;}
function restoreFormDrafts(records){let restored=false;for(const form of $('work-detail').querySelectorAll('[data-work-form]')){const record=records.find(item=>item.key===formKey(form));if(!record)continue;if(record.originForm===form){restored=true;continue;}for(const control of form.querySelectorAll('input[name],textarea[name],select[name]')){const saved=record.fields.find(field=>field.name===control.name&&(!['checkbox','radio'].includes(control.type)||field.value===control.value));if(!saved)continue;if(['checkbox','radio'].includes(control.type))control.checked=saved.checked;else control.value=saved.value;restored=true;}}if(restored)state.formDirty=true;return restored;}
async function write(source,operation){if(state.mutationBusy)return;if(state.planner?.isBusy?.()||state.productionPlan?.isBusy?.()||state.thread?.isBusy?.()){toast('Let the current plan, assistant or reply finish before saving another change.');return;}if(state.capture?.isBusy?.()){toast('Finish the current recording or upload before saving changes.');return;}if(state.capture?.isDirty?.()){toast('Save or discard the recorded take before saving other changes.');return;}const preserved=collectFormDrafts(source?.tagName==='FORM'?source:null),viewKey=state.detail?state.detail.kind+':'+(state.detail.data?.id||''):'';state.mutationBusy=true;filterRosterPicker();const buttons=source?.tagName==='FORM'?[...source.querySelectorAll('button,input[type=submit]')]:source?[source]:[];buttons.forEach(b=>b.disabled=true);const status=source?.querySelector?.('[data-form-status]');if(status)status.textContent='Saving…';clearError();try{await operation();if(state.detail&&state.detail.kind+':'+(state.detail.data?.id||'')===viewKey){restoreFormDrafts(preserved);if(collectFormDrafts().length)state.formDirty=true;}}catch(error){if(status&&status.isConnected)status.textContent='Not saved. Your entries are still here.';throw error;}finally{state.mutationBusy=false;buttons.filter(b=>b.isConnected).forEach(b=>b.disabled=false);if($('work-notification-read-all'))$('work-notification-read-all').disabled=!state.notifications.some(item=>!item.readAt);filterRosterPicker();}}
async function refreshSummary(){await Promise.all([loadList(),loadNotifications(false)]);}

function projectCard(item){const accepted=Number(item.acceptedCount)||0;return '<article class="work-card"><div class="work-card-top"><p class="eyebrow">'+esc(item.productLine||'AZHOTTIE PRODUCTION')+'</p>'+statusBadge(item.status)+'</div><h2>'+esc(item.title)+'</h2><p class="work-description">'+esc(item.brief||'The brief is ready for its first details.')+'</p><div class="work-meta"><span>'+esc(item.kind==='mixed'?'Mixed production':item.kind==='interview'?'Interview':'Production')+'</span><span>'+esc(item.shotCount)+' shot'+(item.shotCount===1?'':'s')+'</span><span>'+esc(item.assignmentCount)+' assignment'+(item.assignmentCount===1?'':'s')+'</span></div><div class="work-progress"><span style="width:'+Math.min(100,(Number(item.approvedAssignmentCount)||0)/Math.max(1,Number(item.assignmentCount))*100)+'%"></span></div><p class="field-help">'+accepted+' accepted takes · '+(Number(item.submittedCount)||0)+' awaiting review</p><div class="work-actions">'+button('Open production','project',item.id,'button--primary')+'</div></article>';}
function memberProjectCard(item){return '<article class="work-card"><div class="work-card-top"><p class="eyebrow">'+esc(item.productLine||'YOUR PRODUCTION')+'</p>'+statusBadge(item.status)+'</div><h2>'+esc(item.title)+'</h2><p class="work-description">'+esc(item.brief||'The producer is preparing the direction for this project.')+'</p><p class="field-help">You are included in this production. Browse its open shots and your own assignments.</p><div class="work-meta"><span>'+esc(item.shotCount||0)+' visible shot'+(Number(item.shotCount)===1?'':'s')+'</span></div><div class="work-actions">'+button('View available shots','project',item.id,'button--primary')+'</div></article>';}

function rosterEditable(project){return !!project?.canManage&&!!project.roster?.canManage&&project.roster.canEdit!==false&&['draft','active'].includes(project.status);}
function rosterRoles(roles=[]){return roles.filter(role=>['model','professional'].includes(role)).map(role=>role==='model'?'Model':'Professional').join(' · ')||'Role unavailable';}
function rosterMarkup(project){
  const roster=project.roster;
  if(!roster)return '<p class="work-inline-notice">The production roster could not be loaded. Reload this production before adding models.</p>';
  const members=roster.members||[],candidates=roster.candidates||[],editable=rosterEditable(project);
  const cards=members.map(member=>'<article class="work-roster-member"><div class="work-roster-person"><span class="work-roster-initial" aria-hidden="true">'+esc((Array.from(String(member.name||'?').trim())[0]||'?').toUpperCase())+'</span><div><h3>'+esc(member.name)+'</h3><p class="field-help">'+esc(rosterRoles(member.roles))+'</p><p class="field-help">'+Number(member.activeAssignmentCount||0)+' current assignment'+(Number(member.activeAssignmentCount)===1?'':'s')+'</p>'+(!member.eligible?'<span class="badge badge--private">'+esc(member.accountStatus!=='active'?'Account inactive':'Role approval needed')+'</span>':'')+'</div></div>'+(editable?button('Remove','roster-remove',String(member.userId),'button--quiet','aria-label="Remove '+esc(member.name)+' from this production"'):'')+'</article>').join('');
  return '<div class="work-section-heading"><div><p class="eyebrow">THE PEOPLE IN THIS PRODUCTION</p><h2>Add models to this production</h2></div><div class="work-actions">'+badge(members.length+' included')+button('Reload roster','roster-reload',project.id,'button--quiet')+'</div></div><p class="field-help work-roster-intro">Included members see this production’s open shots in My work. Assign a specific shot to one of these models, or let eligible members claim an open place.</p><div class="work-roster-members">'+(members.length?cards:'<p class="work-roster-empty">No models are included yet. Add your team below to share available assignments.</p>')+'</div>'+(editable?'<p class="field-help work-roster-removal">Removing someone stops new open claims. Their existing assignments, footage, and review history remain available; cancel an assignment separately when needed.</p>':'<p class="work-inline-notice">Reopen this production to change its models. Existing assignments and footage remain available.</p>')+'<div id="work-roster-notice" class="work-inline-notice" role="status" hidden></div>'+(editable&&members.length<Number(roster.maxMembers||200)?'<div class="work-roster-picker"><div class="work-section-heading"><div><h3>Choose models to include</h3><p class="field-help">Approved model and professional accounts. Adding someone does not assign every shot or reserve a contributor place.</p></div></div>'+(candidates.length?'<label class="field work-roster-search">Find a model<input id="work-roster-search" type="search" autocomplete="off" placeholder="Search by name or role"></label><form data-work-form="roster-add" data-project-id="'+esc(project.id)+'"><fieldset class="work-roster-options"><legend class="sr-only">Available models and professionals</legend>'+candidates.map((candidate,index)=>'<label class="work-roster-option" data-roster-option data-search="'+esc([candidate.name,...(candidate.roles||[])].join(' ').toLowerCase())+'"'+(index>=12?' hidden':'')+'><input type="checkbox" name="memberIds" value="'+Number(candidate.id)+'"><span><strong>'+esc(candidate.name)+'</strong><span>'+esc(rosterRoles(candidate.roles))+'</span></span></label>').join('')+'</fieldset><p id="work-roster-match-count" class="field-help" role="status"></p><div class="work-actions">'+button('Show more models','roster-more',project.id,'button--quiet','id="work-roster-more"'+(candidates.length<=12?' hidden':''))+'<button type="submit" class="button button--primary" id="work-roster-add" disabled>Add selected models</button><span id="work-roster-selected" class="field-help" role="status">0 selected</span></div><p class="work-form-status" data-form-status role="status"></p></form>':'<p class="work-roster-empty">All currently approved accounts are included, or no other model accounts are available. Create or approve model accounts in Accounts; an unlinked casting profile does not receive assignments. '+link('Manage accounts',workPage('accounts'),'button--quiet')+'</p>')+'</div>':editable?'<p class="work-inline-notice">This production has reached its '+Number(roster.maxMembers||200)+'-member limit.</p>':'');
}
function filterRosterPicker(){
  const panel=$('work-roster');if(!panel)return;
  const term=($('work-roster-search')?.value||'').trim().toLowerCase();let matches=0,shown=0;
  for(const control of panel.querySelectorAll('input,button'))control.disabled=state.mutationBusy||(state.rosterStale&&control.dataset?.action==='roster-remove');
  for(const item of panel.querySelectorAll('[data-roster-option]')){const match=!term||item.dataset.search.includes(term);if(match)matches++;item.hidden=!match||shown>=state.rosterLimit;if(match&&!item.hidden)shown++;}
  const selected=[...panel.querySelectorAll('[name=memberIds]:checked')].length;
  if($('work-roster-match-count'))$('work-roster-match-count').textContent=matches?'Showing '+shown+' of '+matches+' matching account'+(matches===1?'':'s')+'.':'No accounts match this search.';
  if($('work-roster-more'))$('work-roster-more').hidden=shown>=matches;
  if($('work-roster-selected'))$('work-roster-selected').textContent=selected+' selected';
  if($('work-roster-add'))$('work-roster-add').disabled=!selected||state.rosterStale||state.mutationBusy;
}
function updateRoster(roster,projectId){
  if(state.detail?.kind!=='project'||state.detail.data.id!==projectId)return false;
  state.detail.data.roster=roster;state.rosterStale=false;state.rosterLimit=12;state.productionPlan?.updateRoster?.(roster);
  const panel=$('work-roster');if(panel){panel.innerHTML=rosterMarkup(state.detail.data);filterRosterPicker();}
  return true;
}
function rosterFailure(error){
  if(error.code!=='revision_conflict')throw error;
  state.rosterStale=true;const notice=$('work-roster-notice');if(notice){notice.hidden=false;notice.setAttribute('role','alert');notice.textContent='This production’s models changed in another window. Your selections are still here. Reload the roster before saving again.';}
  filterRosterPicker();throw error;
}
function assignmentCandidates(shot){
  const assigned=shot.assignments||[],activeAssignment=userId=>assigned.some(item=>String(item.userId)===String(userId)&&!['declined','cancelled'].includes(item.status));
  const members=(shot.roster?.members||[]).filter(member=>member.eligible&&member.accountStatus==='active'&&(member.roles||[]).some(role=>(shot.eligibleRoles||[]).includes(role))&&!activeAssignment(member.userId)&&Number(shot.slotsRemaining)>0).map(member=>({id:member.userId,name:member.name,roles:member.roles,studio:false}));
  const owner=state.boot?.user;
  if(shot.canManage&&owner&&!activeAssignment(owner.id)&&!members.some(member=>String(member.id)===String(owner.id)))members.push({id:owner.id,name:owner.name||'Studio',roles:owner.roles||[],studio:true});
  return members;
}
function shotCard(item){return '<article class="work-card"><div class="work-card-top"><p class="eyebrow">'+esc(item.projectTitle||'SHOT '+((Number(item.sortOrder)||0)+1))+'</p>'+badge(item.mode==='open'?'Open shot':'Assigned shot',item.mode==='open'?'badge--accent':'')+'</div><h3>'+esc(item.title)+'</h3><p class="work-description">'+esc(item.brief||'View the shot details for the full direction.')+'</p>'+metadata(item)+'<div class="work-badges">'+statusBadge(item.status)+(item.mode==='open'&&Number.isFinite(item.slotsRemaining)?badge(item.slotsRemaining+' place'+(item.slotsRemaining===1?'':'s')+' available'):'')+'</div><div class="work-actions">'+button('View shot','shot',item.id,item.canClaim?'button--primary':'')+(item.myAssignment?button('My assignment','assignment',item.myAssignment.id):'')+'</div></article>';}
function assignmentCard(item){return '<article class="work-card"><div class="work-card-top"><p class="eyebrow">'+esc(item.projectTitle)+'</p>'+statusBadge(item.status)+'</div><h3>'+esc(item.shotTitle)+'</h3>'+metadata(item)+(item.latestReviewNote?'<p class="work-feedback">'+esc(item.latestReviewNote)+'</p>':'')+(item.questionUnreadCount?'<p class="field-help"><span class="work-count-pill">'+Number(item.questionUnreadCount)+'</span> unread '+(Number(item.questionUnreadCount)===1?'reply':'replies')+'</p>':'')+'<div class="work-meta"><span>'+esc(item.submissionCount||0)+' uploaded take'+(Number(item.submissionCount)===1?'':'s')+'</span>'+(item.acceptedCount?'<span>'+esc(item.acceptedCount)+' accepted</span>':'')+'</div><div class="work-actions">'+button(item.canRespond?'Review assignment':item.canUpload?'Open workspace':'View submissions','assignment',item.id,'button--primary')+'</div></article>';}
function renderList(){if(!state.boot)return;const term=($('work-search')?.value||'').trim().toLowerCase();let items,renderer,emptyTitle,emptyDescription;if(adminPage){const status=$('work-project-status').value;items=state.projects.filter(p=>(status==='all'||status==='active'&&['active','draft'].includes(p.status)||p.status===status)&&(!term||[p.title,p.brief,p.productLine].join(' ').toLowerCase().includes(term)));renderer=projectCard;emptyTitle=term?'No matching productions':'Make room for the next story';emptyDescription=term?'Try another title, product line, or status.':'Start with a brief, then add the shots and people who will bring it to life.';$('work-metrics').innerHTML=metrics([['In progress',state.projects.filter(p=>p.status==='active').length],['Drafts',state.projects.filter(p=>p.status==='draft').length],['Awaiting review',state.projects.reduce((s,p)=>s+(Number(p.submittedCount)||0),0)],['Accepted takes',state.projects.reduce((s,p)=>s+(Number(p.acceptedCount)||0),0)]]);}else{const bucket=state.tab==='submissions'?'submitted':state.tab;items=(state.mine[bucket]||[]).filter(p=>!term||[p.title,p.shotTitle,p.projectTitle,p.brief].join(' ').toLowerCase().includes(term));renderer=state.tab==='projects'?memberProjectCard:state.tab==='open'?shotCard:assignmentCard;const copy={projects:['Your productions will appear here','A producer can add you to a production before any individual shots are assigned.'],assigned:['Your next assignment starts here','New assignments and requested retakes will appear here. You can also browse open shots.'],open:['No open shots right now','Open assignments appear from productions you are included in, when a place is available for your account roles.'],submissions:['Nothing waiting in review','Upload your takes from an assignment and submit them when you are ready.'],completed:['Your finished work belongs here','Approved assignments, feedback, and published videos will appear here.']};[emptyTitle,emptyDescription]=term?['No matching work','Try another project or shot title.']:copy[state.tab];$('work-metrics').innerHTML=metrics([['Productions',(state.mine.projects||[]).length],['Assigned',state.mine.assigned.length],['Open shots',state.mine.open.length],['In review',state.mine.submitted.length],['Completed',state.mine.completed.length]]);document.querySelectorAll('[data-work-tab]').forEach(b=>{const active=b.dataset.workTab===state.tab;b.classList.toggle('is-active',active);b.setAttribute('aria-pressed',String(active));});}
  $('work-list-count').textContent=items.length+' '+(adminPage||state.tab==='projects'?'production'+(items.length===1?'':'s'):state.tab==='open'?'open shot'+(items.length===1?'':'s'):'assignment'+(items.length===1?'':'s'))+(term?' matching “'+$('work-search').value+'”':'');$('work-list').innerHTML=items.length?items.slice(0,state.limit).map(renderer).join(''):empty(emptyTitle,emptyDescription,adminPage&&!term?button('Create a production','new-project','','button--primary'):'');$('work-more').hidden=items.length<=state.limit;}
async function loadList(){const request=++state.listRequest;const data=await api(adminPage?'projects':'myWork');if(request!==state.listRequest)return;if(adminPage)state.projects=data;else state.mine={projects:[],assigned:[],open:[],submitted:[],completed:[],...data};renderList();}

function references(items=[]){if(!items.length)return '<p class="field-help">No reference images have been added.</p>';return '<div class="work-reference-grid">'+items.map(item=>'<figure class="work-reference"><a href="'+esc(safeUrl(item.mediaUrl))+'" target="_blank" rel="noopener"><img src="'+esc(safeUrl(item.mediaUrl))+'" alt="'+esc(item.title||'Shot reference')+'" loading="lazy"></a><figcaption>'+esc(item.title||'Reference image')+'</figcaption></figure>').join('')+'</div>';}
function referenceForm(projectId,shotId=''){return '<form class="work-reference-upload" data-work-form="reference" data-project-id="'+esc(projectId)+'" data-shot-id="'+esc(shotId)+'"><div class="work-form-grid">'+field('title','Reference title','','text','maxlength="200"')+'<label class="field">Image<input type="file" name="file" accept="image/jpeg,image/png,image/webp" required><span class="field-help">JPEG, PNG, or WebP. Up to 20 MB.</span></label></div><div class="work-actions"><button type="submit" class="button">Upload reference</button></div><p class="work-form-status" data-form-status role="status"></p></form>';}
function scheduleDetails(project){const schedule=project.schedule;if(!schedule)return '<p class="field-help">No event or appointment is linked yet.</p>';return '<h3>'+esc(schedule.title)+'</h3><p>'+esc(localDate(schedule.startLocal))+' · Arizona</p>'+(schedule.location?'<p class="field-help">'+esc(schedule.location)+'</p>':'')+'<div class="work-actions">'+link(schedule.type==='event'?'View event':'View appointments',workPage(schedule.type==='event'?'calendar':'appointments',schedule.type==='event'?{eventId:schedule.id}:{tab:'mine'}))+'</div>';}
