    html+=users.length&&accepting?'<form data-work-form="assign" class="work-assignment-tools">'+select('userId','Assign this shot',users.map(u=>[u.id,u.studio?'Studio · me':u.name+' · '+rosterRoles(u.roles)]),'')+'<button type="submit" class="button button--primary">Assign shot</button><p class="work-form-status" data-form-status role="status"></p></form>':'<p class="field-help">'+esc(!['draft','active'].includes(shot.project?.status)?'Reopen the production before assigning contributors.':shot.slotsRemaining<1?'All model contributor places are taken. Edit the shot to increase capacity.':!users.length?'Add an eligible model to this production, or check their existing assignment.':'This shot is not accepting new assignments.')+'</p>';
