function shotForm(projectId,shot=null){const item=shot||{projectId,title:'',brief:'',mode:'assigned',maxContributors:1,eligibleRoles:['model'],orientation:'portrait',targetDurationSeconds:30,takesRequested:2,dueLocal:'',sortOrder:state.detail?.data?.shots?.length||0,status:'active'};const html='<form class="panel work-panel work-form" data-work-form="shot"><p class="eyebrow">CLEAR DIRECTION, ROOM TO CREATE</p><h2>'+esc(shot?'Edit shot':'Add a shot')+'</h2>'+field('title','Shot title',item.title,'text','required maxlength="200" placeholder="The first-look reveal"')+area('brief','Shot direction',item.brief,16000)+'<div class="work-form-grid">'+select('mode','How contributors join',[['assigned','Assigned · invite specific members'],['open','Open · included models can claim']],item.mode)+field('maxContributors','Maximum contributors',item.maxContributors,'number','required min="1" max="50"')+select('orientation','Video orientation',[['portrait','Portrait · 9:16'],['landscape','Landscape · 16:9'],['square','Square · 1:1'],['any','Any orientation']],item.orientation)+field('targetDurationSeconds','Target length · seconds',item.targetDurationSeconds,'number','required min="0" max="3600"')+field('takesRequested','Takes requested per contributor',item.takesRequested,'number','required min="1" max="20"')+field('dueLocal','Deadline · Arizona time',item.dueLocal||'','datetime-local')+field('sortOrder','Shot order · starts at 1',Number(item.sortOrder)+1,'number','required min="1" max="10001"')+select('status','Availability',[['active','Active'],['closed','Closed · no new uploads'],['archived','Archived']],item.status)+'</div><fieldset><legend>Eligible account roles</legend><div class="work-role-options">'+['model','professional'].map(role=>'<label class="checkbox-field"><input type="checkbox" name="eligibleRoles" value="'+role+'"'+(item.eligibleRoles.includes(role)?' checked':'')+'>'+esc(role==='model'?'Models':'Professionals')+'</label>').join('')+'</div><p class="field-help">Included members qualify with either selected role. Each open claim uses one contributor place.</p></fieldset>'+formActions('Save shot')+'</form>';setDetail(html,'shot-form',item,{route:false});}
function submissionCard(item,assignment){const url=safeUrl(item.mediaUrl),reviewable=item.canReview;return '<article class="work-take" data-submission-id="'+esc(item.id)+'"><div class="work-card-top"><h3>'+esc(item.label||item.fileName||'Video take')+'</h3>'+statusBadge(item.status)+'</div>'+(url?'<video id="take-'+esc(item.id)+'" controls playsinline preload="metadata" src="'+esc(url)+'"></video>':'<p class="field-help">The video is not available.</p>')+'<div class="work-meta">'+(item.sourceLabel?'<span>'+esc(item.sourceLabel)+'</span>':'')+'<span>'+esc(item.durationMs?duration(item.durationMs/1000):'Duration pending')+'</span><span>'+esc(size(item.sizeBytes||0))+'</span><span>Uploaded '+esc(date(item.createdAt))+'</span></div>'+(item.note?'<p>'+esc(item.note)+'</p>':'')+(item.reviewNote?'<div class="work-feedback"><strong>Producer feedback</strong><p>'+esc(item.reviewNote)+'</p></div>':'')+(assignment.canManage?'<div class="work-actions">'+button(item.isFavorite?'Remove favorite':'Mark favorite','favorite',item.id,item.isFavorite?'button--primary':'','aria-pressed="'+String(!!item.isFavorite)+'"')+'</div>':'')+(reviewable?'<form class="work-submission-form" data-work-form="review" data-submission-id="'+esc(item.id)+'">'+area('note','Review note',item.reviewNote||'',4000)+'<div class="work-actions"><button type="submit" name="decision" value="accepted" class="button button--primary">Accept take</button><button type="submit" name="decision" value="retake" class="button">Request retake</button></div><p class="work-form-status" data-form-status role="status"></p></form>':'')+((item.reviewNotes||[]).length?'<div class="work-notes"><h4>Timestamped notes</h4>'+item.reviewNotes.map(note=>'<div class="work-note"><div><button type="button" class="text-button" data-action="seek-note" data-id="'+esc(item.id)+'" data-ms="'+Number(note.atMs)+'">'+esc(timecode(note.atMs))+'</button><p>'+esc(note.text)+'</p></div>'+(assignment.canManage?button('Remove note','remove-note',item.id,'button--quiet','data-note-id="'+esc(note.id)+'"'):'')+'</div>').join('')+'</div>':'')+(assignment.canManage?'<form class="work-note-form" data-work-form="take-note" data-submission-id="'+esc(item.id)+'">'+field('seconds','Time · seconds','0','number','required min="0" max="86400" step="0.1"')+field('text','Add a review note','','text','required maxlength="2000"')+'<div class="work-actions">'+button('Use playhead','playhead',item.id)+'<button type="submit" class="button">Save note</button></div><p class="work-form-status" data-form-status role="status"></p></form>':'')+'</article>';}
