function renderNotifications(){const unread=state.notifications.filter(n=>!n.readAt).length;$('work-unread-count').textContent=String(unread);$('work-unread-count').hidden=!unread;$('work-notification-read-all').disabled=!unread;$('work-notification-list').innerHTML=state.notifications.length?state.notifications.map(n=>'<article class="work-notification'+(!n.readAt?' is-unread':'')+'"><div><strong>'+esc(n.title)+'</strong><p>'+esc(n.message)+'</p><time>'+esc(date(n.createdAt,true))+'</time></div><div class="work-actions">'+button('View','notification',n.id,'button--small')+'</div></article>').join(''):empty('You’re all caught up','Assignments, submissions, and review updates will appear here.');}
async function loadNotifications(render=true){const request=++state.notificationRequest;const result=await api('notifications');if(request!==state.notificationRequest)return;state.notifications=result.notifications||[];$('work-unread-count').textContent=String(result.unreadCount||0);$('work-unread-count').hidden=!result.unreadCount;if(render||!$('work-notifications').hidden)renderNotifications();}
async function refreshDetail(options={}){const detail=state.detail;if(!detail)return;if(detail.kind==='project')await openProject(detail.data.id,{force:true,scroll:false,...options});if(detail.kind==='shot')await openShot(detail.data.id,{force:true,scroll:false,...options});if(detail.kind==='assignment')await openAssignment(detail.data.id,{force:true,scroll:false,...options});}
async function chooseTab(tab,options={}){if(!['projects','assigned','open','submissions','completed'].includes(tab)||!options.force&&!canLeave())return;state.tab=tab;state.limit=18;showList({force:true,replace:options.replace});await loadList();}
async function action(node){const name=node.dataset.action,id=node.dataset.id;if(name==='list'){showList();return;}if(name==='project')return openProject(id);if(name==='roster-project')return openProject(id,{rosterFocus:true});if(name==='shot')return openShot(id);if(name==='assignment')return openAssignment(id);if(name==='new-project'){if(canLeave())projectForm();return;}if(name==='edit-project'){if(canLeave())projectForm(state.detail.data);return;}if(name==='new-shot'){if(canLeave())shotForm(id);return;}if(name==='edit-shot'){if(canLeave())shotForm(state.detail.data.projectId,state.detail.data);return;}if(name==='back'){if(!canLeave())return;const detail=state.detail;if(detail?.kind==='project-form'&&detail.data)return openProject(detail.data.id,{force:true});if(detail?.kind==='shot-form')return detail.data.id?openShot(detail.data.id,{force:true}):openProject(detail.data.projectId,{force:true});return showList({force:true});}
  if(name==='roster-more'){state.rosterLimit+=12;filterRosterPicker();return;}
  if(name==='roster-reload')return write(node,async()=>{const project=state.detail?.kind==='project'?state.detail.data:null;if(!project)return;const roster=await api('roster',null,{projectId:project.id});updateRoster(roster,project.id);toast('Production models reloaded. Review your remaining selections before adding them.');});
  if(name==='roster-remove'){
    const project=state.detail?.kind==='project'?state.detail.data:null,member=project?.roster?.members?.find(item=>String(item.userId)===String(id));
    if(!member||!rosterEditable(project)||state.rosterStale)return;
    return write(node,async()=>{const roster=await api('removeMember',{projectId:project.id,revision:project.roster.revision,userId:Number(id)}).catch(rosterFailure);updateRoster(roster,project.id);await refreshSummary();toast(member.name+' removed from the production roster. Existing assignments remain.');});
  }
  if(name==='claim')return write(node,async()=>{const assignment=await api('claim',{shotId:id});state.formDirty=false;await openAssignment(assignment.id,{force:true});await refreshSummary();toast('This shot is yours. Your workspace is ready.');});
  if(name==='cancel-assignment'){const assignment=findAssignment(id);if(!assignment)return;if(!confirm('Cancel '+assignment.userName+'’s assignment? Saved takes and review history will remain.'))return;return write(node,async()=>{await api('cancelAssignment',{assignmentId:id,revision:assignment.revision,note:''});state.formDirty=false;await refreshDetail();await refreshSummary();toast('Assignment cancelled.');});}
  if(name==='favorite'){const take=state.detail?.data?.submissions?.find(s=>s.id===id);if(!take)return;return write(node,async()=>{const result=await api('favoriteSubmission',{submissionId:id,favorite:!take.isFavorite});take.isFavorite=result.isFavorite;node.textContent=take.isFavorite?'Remove favorite':'Mark favorite';node.classList.toggle('button--primary',!!take.isFavorite);node.setAttribute('aria-pressed',String(!!take.isFavorite));toast(take.isFavorite?'Take marked as a favorite.':'Favorite removed.');});}
  if(name==='playhead'){const video=$('take-'+id),form=node.closest('form');if(video&&form){form.querySelector('[name=seconds]').value=(Number(video.currentTime)||0).toFixed(1);state.formDirty=true;}return;}
  if(name==='seek-note'){const video=$('take-'+id);if(video){video.currentTime=Math.max(0,Number(node.dataset.ms)/1000||0);video.focus();}return;}
  if(name==='remove-note')return write(node,async()=>{await api('deleteSubmissionNote',{submissionId:id,noteId:node.dataset.noteId});state.formDirty=false;await refreshDetail();toast('Review note removed.');});
  if(name==='prepare-editor')return write(node,async()=>{const result=await mediaApi('prepareEditor',{projectId:id});const url=safeUrl(result.editorUrl);if(!url)throw new Error('The editor link was not returned. Please refresh this production.');state.formDirty=false;cleanup();location.href=url;});
  if(name==='load-sources')return write(node,async()=>{const sources=await mediaApi('sourceInterviews',null,{projectId:id});const options=sources.flatMap(source=>(source.takes||[]).map(take=>[take.id,source.title+' · '+(take.label||take.questionText||'Recorded take')+' · '+duration(take.durationMs/1000)]));$('work-source-list').innerHTML=options.length?'<form data-work-form="import-source" class="work-form">'+select('takeId','Recorded interview take',options,'')+'<button type="submit" class="button button--primary">Add interview take to edit</button><p class="work-form-status" data-form-status role="status"></p></form>':'<p class="field-help">No eligible recorded interview footage is available to import.</p>';});
  if(name==='notification'){if(!canLeave())return;const notice=state.notifications.find(n=>n.id===id);if(!notice)return;await api('markNotificationsRead',{ids:[id]});await loadNotifications();$('work-notifications').hidden=true;$('work-notification-toggle').setAttribute('aria-expanded','false');if(notice.assignmentId)return openAssignment(notice.assignmentId,{force:true});if(notice.projectId)return openProject(notice.projectId,{force:true});return;}
}
async function submit(form,submitter){const values=Object.fromEntries(new FormData(form)),kind=form.dataset.workForm,current=state.detail?.data;if(kind==='project'){const [type,id]=(values.scheduleLink||'').split(':');delete values.scheduleLink;Object.assign(values,{eventId:type==='event'?id:null,appointmentId:type==='appointment'?id:null});if(current)Object.assign(values,{id:current.id,revision:current.revision});return write(form,async()=>{const project=await api('saveProject',values);state.formDirty=false;await openProject(project.id,{force:true});await refreshSummary();toast('Production saved.');});}
  if(kind==='roster-add'){
    if(!rosterEditable(current)||state.rosterStale)return;
    const userIds=[...form.querySelectorAll('[name=memberIds]:checked')].map(input=>Number(input.value));
    if(!userIds.length)throw new Error('Select at least one model to include.');
    return write(form,async()=>{const roster=await api('addMembers',{projectId:current.id,revision:current.roster.revision,userIds}).catch(rosterFailure);state.formDirty=false;updateRoster(roster,current.id);await refreshSummary();toast(userIds.length+' member'+(userIds.length===1?'':'s')+' added. Open shots are available when this production is in progress.');});
  }
  if(kind==='shot'){values.projectId=current.projectId;for(const key of ['maxContributors','targetDurationSeconds','takesRequested','sortOrder'])values[key]=Number(values[key]);values.sortOrder--;values.dueLocal=values.dueLocal||null;values.eligibleRoles=[...form.querySelectorAll('[name=eligibleRoles]:checked')].map(e=>e.value);if(!values.eligibleRoles.length)throw new Error('Choose at least one eligible account role.');if(current.id)Object.assign(values,{id:current.id,revision:current.revision});return write(form,async()=>{const shot=await api('saveShot',values);state.formDirty=false;await openShot(shot.id,{force:true});await refreshSummary();toast('Shot saved.');});}
  if(kind==='assign')return write(form,async()=>{await api('assign',{shotId:current.id,userId:Number(values.userId)});state.formDirty=false;await refreshDetail();await refreshSummary();toast('Assignment sent. The member will see it in My work.');});
  if(kind==='respond'){const decision=submitter?.value;if(!['accept','decline'].includes(decision))throw new Error('Choose Accept or Decline.');return write(form,async()=>{await api('respond',{assignmentId:current.id,revision:current.revision,decision,note:values.note});state.formDirty=false;await refreshDetail();await refreshSummary();toast(decision==='accept'?'Assignment accepted. You can record or upload your takes.':'Assignment declined. Your note was saved for the producer.');});}
  if(kind==='submit'){if(state.capture?.isBusy?.())throw new Error('Finish the current upload or recording before submitting.');return write(form,async()=>{await api('submitAssignment',{assignmentId:current.id,revision:current.revision,note:values.note});state.formDirty=false;await refreshDetail();await refreshSummary();toast('Your takes are in review. You will see feedback here.');});}
  if(kind==='review'){const take=current.submissions.find(s=>s.id===form.dataset.submissionId),decision=submitter?.value;if(!take||!['accepted','retake'].includes(decision))return;if(decision==='retake'&&!values.note.trim())throw new Error('Add a note so the contributor knows what to change in the retake.');return write(form,async()=>{await api('reviewSubmission',{submissionId:take.id,revision:take.revision,decision,note:values.note});state.formDirty=false;await refreshDetail();await refreshSummary();toast(decision==='accepted'?'Take accepted. It is available for the production edit.':'Retake requested. The contributor can upload a new take.');});}
  if(kind==='take-note'){const take=current.submissions.find(s=>s.id===form.dataset.submissionId);if(!take)return;const atMs=Math.round(Number(values.seconds)*1000);if(!Number.isFinite(atMs)||atMs<0)throw new Error('Enter a valid time for the review note.');return write(form,async()=>{await api('addSubmissionNote',{submissionId:take.id,atMs,text:values.text});state.formDirty=false;await refreshDetail();toast('Timestamped note saved.');});}
  if(kind==='reference'){const file=form.querySelector('[name=file]').files[0];if(!file)throw new Error('Choose a reference image.');if(file.size>20*1048576)throw new Error('Choose a reference image smaller than 20 MB.');const payload=new FormData(form);payload.set('projectId',form.dataset.projectId);if(form.dataset.shotId)payload.set('shotId',form.dataset.shotId);return write(form,async()=>{await mediaApi('uploadReference',payload);state.formDirty=false;await refreshDetail();toast('Reference image uploaded.');});}
  if(kind==='import-source')return write(form,async()=>{await mediaApi('importSource',{projectId:current.id,takeId:values.takeId});state.formDirty=false;await refreshDetail();await refreshSummary();toast('Interview take added. Open the editor to arrange it with your accepted production footage.');});
}

document.addEventListener('click',event=>{const node=event.target.closest('[data-action]');if(node){event.preventDefault();if(state.mutationBusy)return;Promise.resolve().then(()=>action(node)).catch(fail);return;}const tab=event.target.closest('[data-work-tab]');if(tab){event.preventDefault();Promise.resolve().then(()=>chooseTab(tab.dataset.workTab)).catch(fail);return;}const anchor=event.target.closest('a[href]');if(anchor&&state.detail&&!anchor.target&&new URL(anchor.href,location.href).pathname!==location.pathname&&!canLeave())event.preventDefault();});
document.addEventListener('submit',event=>{const form=event.target;if(!form.matches('[data-work-form]'))return;event.preventDefault();if(state.mutationBusy)return;Promise.resolve().then(()=>submit(form,event.submitter)).catch(fail);});
document.addEventListener('input',event=>{if(event.target.id==='work-roster-search'){state.rosterLimit=12;filterRosterPicker();return;}if(event.target.closest('[data-work-form]'))state.formDirty=true;if(event.target.name==='memberIds')filterRosterPicker();});
document.addEventListener('change',event=>{if(event.target.closest('[data-work-form]'))state.formDirty=true;if(event.target.name==='memberIds')filterRosterPicker();});
window.addEventListener('beforeunload',event=>{if(state.formDirty||state.mutationBusy||state.capture?.isBusy?.()||state.capture?.isDirty?.()||state.planner?.isBusy?.()||state.planner?.isDirty?.()||state.productionPlan?.isBusy?.()||state.productionPlan?.isDirty?.()||state.thread?.isBusy?.()||state.thread?.isDirty?.()){event.preventDefault();event.returnValue='';}});
async function route(){const params=new URLSearchParams(location.search);if(!adminPage&&['projects','assigned','open','submissions','completed'].includes(params.get('tab')))state.tab=params.get('tab');const assignment=params.get('assignmentId')||params.get('assignment'),shot=params.get('shotId')||params.get('shot'),project=params.get('projectId')||params.get('project')||params.get('id');if(assignment)return openAssignment(assignment,{force:true,replace:true});if(shot)return openShot(shot,{force:true,replace:true});if(project)return openProject(project,{force:true,replace:true});showList({force:true,replace:true});}
window.addEventListener('popstate',()=>{if(!canLeave()){history.pushState(null,'',state.route||location.pathname);return;}route().catch(fail);});
async function start(){state.boot=await api('bootstrap');setWorkCsrf(state.boot.csrf);if(adminPage&&!state.boot.canManage){$('work-new-project').hidden=true;throw new Error('Production management is available to administrators. Open My work to see your assignments.');}on('work-new-project','click',()=>{if(canLeave())projectForm();});on('work-search','input',()=>{state.limit=18;renderList();});on('work-project-status','change',()=>{state.limit=18;renderList();});on('work-more','click',()=>{state.limit+=18;renderList();});on('work-refresh','click',()=>write($('work-refresh'),async()=>{await refreshSummary();toast('Your work is up to date.');}));on('work-notification-toggle','click',async()=>{const open=$('work-notifications').hidden;$('work-notifications').hidden=!open;$('work-notification-toggle').setAttribute('aria-expanded',String(open));if(open)await loadNotifications();});on('work-notification-read-all','click',()=>write($('work-notification-read-all'),async()=>{await api('markNotificationsRead',{all:true});await loadNotifications();toast('Updates marked as read.');}));await Promise.all([loadList(),loadNotifications(false)]);await route();state.initializing=false;}
start().catch(fail);
